  window.getMotionFormSvg = function(key) {
    if (!key) return FORMS[0];
    const str = String(key).toLowerCase().trim();
    if (str.includes('the-lie-of-being-yourself') || str.includes('being-yourself')) {
      return FORMS[0]; // Whirlwind for the flagship post
    }
    let hash = 2166136261;
    for (let i = 0; i < str.length; i++) {
      hash ^= str.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    const idx = (hash >>> 0) % FORMS.length;
    return FORMS[idx];
  };

